  const addSection=title=>{ensure(28);y-=5;page.commands.push('0.90 0.94 0.97 rg',`${M} ${y-16} ${contentWidth} 21 re f`);y-=12;textAt(String(title).toUpperCase(),M+6,y,9,true,'0.043 0.122 0.2');y-=13};
