  if((record.furniture||[]).length){addSection('Furniture / Issued Items');record.furniture.forEach(x=>addText(`${x.item}: expected ${x.expected}; present ${x.present}; rating ${x.rating||'-'}${x.condition?`; condition ${x.condition}`:''}${x.comments?`; ${x.comments}`:''}`,8))}
